            is_prime = True
        if len(word) > 1 and all(len(word) % i != 0 for i in range(2, len(word))):
            is_prime = True

        # A simpler way to check primality:
        is_prime = False
        if len(word) > 1:
            for i in range(2, int(len(word)**0.5) + 1):
                if len(word) % i == 0:
