def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    primes = []
    # The problem description and examples are slightly contradictory.
    # "returns an array of the first n integers that are prime numbers and less than n"
    # If n=5, it asks for the first 5 primes less than 5? No, it returns [2,3].
    # This suggests it means "return all prime numbers less than n".
    # Let's follow the examples: count_up_to(N) returns all primes p such that p < N.
