    For example:
    specialFilter([15, -73, 14, -15]) => 1 
    specialFilter([33, -2, -3, 45, 21, 109]) => 2
    """
    count = 0
    for num in nums:
        if num > 10:
            s_num = str(abs(num))
            if s_num:
                first_digit = int(s_num[0])
                last_digit = int(s_num[-1])

                def is_odd(digit):
                    return digit % 2 != 0

                if is_odd(first_digit) and is_odd(last_digit):
                    count += 1
    return count

