     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    s = str(abs(num))
    even_count = 0
    odd_count = 0
    for digit in s:
        d = int(digit)
        if d % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

